/* Base Setup */
* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background-color: #0f172a;
  color: #f8fafc;
  display: grid;
  place-items: center;
  min-height: 100vh;
  padding: 16px;
}

/* App Container */
.app {
  width: min(460px, 100%);
  background: #1e293b;
  padding: 32px 28px;
  border-radius: 20px;
  border: 1px solid #334155;
  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.4);
}

/* Headings & Subtitles */
h1 {
  margin: 0 0 6px;
  font-size: 28px;
  font-weight: 700;
  letter-spacing: -0.5px;
}

.subtitle {
  margin: 0 0 24px;
  color: #94a3b8;
  font-size: 14px;
}

/* Input & Add Button Row */
.row {
  display: flex;
  gap: 10px;
  margin-bottom: 20px;
}

.row input {
  flex: 1;
  padding: 12px 16px;
  border-radius: 12px;
  border: 1px solid #334155;
  background: #0f172a;
  color: #f8fafc;
  font-size: 14px;
  transition: all 0.2s ease;
}

.row input::placeholder {
  color: #64748b;
}

.row input:focus {
  outline: none;
  border-color: #22c55e;
  box-shadow: 0 0 0 3px rgba(34, 197, 94, 0.2);
}

/* Primary Button */
.btn-primary {
  padding: 12px 20px;
  border: 0;
  border-radius: 12px;
  background: #22c55e;
  color: #05240f;
  font-weight: 700;
  font-size: 14px;
  cursor: pointer;
  transition: all 0.2s ease;
}

.btn-primary:hover {
  background: #16a34a;
  transform: translateY(-1px);
}

.btn-primary:active {
  transform: translateY(0);
}

/* List Formatting */
ul {
  list-style: none;
  padding: 0;
  margin: 0;
}

/* Add entry animation */
@keyframes slideIn {
  from {
    opacity: 0;
    transform: translateY(-8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

li {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
  margin-bottom: 10px;
  background: #0f172a;
  border: 1px solid #334155;
  border-radius: 12px;
  transition: all 0.2s ease;
  animation: slideIn 0.2s ease-out forwards;
}

li:hover {
  border-color: #475569;
}

li.done {
  opacity: 0.6;
}

li.done span {
  text-decoration: line-through;
  color: #64748b;
}

li span {
  flex: 1;
  font-size: 15px;
  word-break: break-word;
  transition: color 0.2s ease;
}

/* Custom Checkbox */
li input[type="checkbox"] {
  appearance: none;
  width: 20px;
  height: 20px;
  border: 2px solid #475569;
  border-radius: 6px;
  background-color: transparent;
  cursor: pointer;
  display: grid;
  place-content: center;
  transition: all 0.2s ease;
}

li input[type="checkbox"]:checked {
  background-color: #22c55e;
  border-color: #22c55e;
}

li input[type="checkbox"]:checked::before {
  content: "✓";
  color: #05240f;
  font-size: 13px;
  font-weight: 900;
}

li input[type="checkbox"]:focus-visible {
  outline: 2px solid #22c55e;
  outline-offset: 2px;
}

/* Delete Button */
.remove {
  background: transparent;
  border: 0;
  color: #64748b;
  font-size: 16px;
  padding: 4px 8px;
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.15s ease;
  opacity: 0; /* Hidden by default until hover */
}

li:hover .remove,
.remove:focus-visible {
  opacity: 1;
}

.remove:hover {
  background: rgba(248, 113, 113, 0.15);
  color: #f87171;
}

/* Empty State */
.empty-state {
  text-align: center;
  color: #64748b;
  padding: 24px 0;
  font-size: 14px;
}

/* Footer Controls */
.footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 20px;
  padding-top: 16px;
  border-top: 1px solid #334155;
  color: #94a3b8;
  font-size: 13px;
}

.btn-clear {
  background: none;
  border: none;
  color: #94a3b8;
  font-size: 13px;
  cursor: pointer;
  padding: 4px 8px;
  border-radius: 6px;
  transition: all 0.2s ease;
}

.btn-clear:hover {
  color: #f87171;
  background: rgba(248, 113, 113, 0.1);
}

function TodoApp() {
  const [items, setItems] = React.useState([
    { id: 1, text: "Learn React in CodX Editor", done: true },
    { id: 2, text: "Build something cool", done: false }
  ]);
  const [draft, setDraft] = React.useState("");

  function addItem() {
    if (!draft.trim()) return;
    setItems([...items, { id: Date.now(), text: draft.trim(), done: false }]);
    setDraft("");
  }

  function toggle(id) {
    setItems(items.map((item) =>
      item.id === id ? { ...item, done: !item.done } : item
    ));
  }

  function remove(id) {
    setItems(items.filter((item) => item.id !== id));
  }

  function clearCompleted() {
    setItems(items.filter((item) => !item.done));
  }

  const left = items.filter((i) => !i.done).length;
  const hasCompleted = items.some((i) => i.done);

  return (
    <div className="app">
      <h1>My Tasks</h1>
      <p className="subtitle">Built with React, running in CodX Editor</p>

      <div className="row">
        <input
          value={draft}
          placeholder="What needs doing?"
          onChange={(e) => setDraft(e.target.value)}
          onKeyDown={(e) => { if (e.key === "Enter") addItem(); }}
        />
        <button className="btn-primary" onClick={addItem}>Add</button>
      </div>

      {items.length === 0 ? (
        <p className="empty-state">No tasks yet! Add one above.</p>
      ) : (
        <ul>
          {items.map((item) => (
            <li key={item.id} className={item.done ? "done" : ""}>
              <input 
                type="checkbox" 
                checked={item.done} 
                onChange={() => toggle(item.id)} 
                aria-label={`Mark "${item.text}" as ${item.done ? "incomplete" : "complete"}`}
              />
              <span>{item.text}</span>
              <button 
                className="remove" 
                onClick={() => remove(item.id)}
                aria-label={`Delete task "${item.text}"`}
              >
                ✕
              </button>
            </li>
          ))}
        </ul>
      )}

      {items.length > 0 && (
        <div className="footer">
          <span>{left} task{left === 1 ? "" : "s"} left</span>
          {hasCompleted && (
            <button className="btn-clear" onClick={clearCompleted}>
              Clear completed
            </button>
          )}
        </div>
      )}
    </div>
  );
}

const root = ReactDOM.createRoot(document.getElementById("root"));
root.render(<TodoApp />);
